```yaml
name: Continue Agents
on:
  workflow_call:
    inputs:
      agents-path:
        description: "Path to continue agents directory"
        required: false
        type: string
        default: ".continue/agents"

jobs:
  run-agents:
    name: Run Continue Agents
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4

      - name: Setup Node.js
        uses: actions/setup-node@v4
        with:
          node-version: "20.x"

      - name: Install Continue CLI
        run: |
          npm install -g @continuedev/cli

      - name: Discover agents
        id: discover
        run: |
          AGENTS_PATH="${{ inputs.agents-path }}"
          if [ ! -d "$AGENTS_PATH" ]; then
            echo "No agents directory found at $AGENTS_PATH"
            echo "agents=[]" >> $GITHUB_OUTPUT
          else
            find "$AGENTS_PATH" -name "*.md" -type f | sort | sed 's/\.md$//' | sed 's/.*\///' > /tmp/agents.txt
            if [ -s /tmp/agents.txt ]; then
              AGENTS=$(cat /tmp/agents.txt | jq -R . | jq -s .)
              echo "agents=$AGENTS" >> $GITHUB_OUTPUT
            else
              echo "agents=[]" >> $GITHUB_OUTPUT
            fi
          fi

      - name: Run agents
        if: steps.discover.outputs.agents != '[]'
        id: run-agents
        uses: actions/github-script@v7
        with:
          script: |
            const agents = ${{ steps.discover.outputs.agents }};
            const agentsPath = "${{ inputs.agents-path }}";

            // Create job summary header
            let summary = "# Continue Agents Results\n\n";

            // Create check runs map
            const checkRuns = {};

            // Run each agent in parallel
            const promises = agents.map(async (agent) => {
              const agentName = agent;
              const agentPath = `${agentsPath}/${agent}.md`;

              // Create check run
              const checkRun = await github.rest.checks.create({
                owner: context.repo.owner,
                repo: context.repo.repo,
                name: `Continue Agent: ${agentName}`,
                head_sha: context.sha,
                status: 'in_progress',
                details_url: `https://github.com/${context.repo.owner}/${context.repo.repo}/blob/${context.sha}/${agentPath}`
              });

              checkRuns[agentName] = checkRun.data.id;

              try {
                // Run the agent using continue CLI
                const { execSync } = require('child_process');
                const output = execSync(`continue run --file "${agentPath}"`, { encoding: 'utf8', stdio: 'pipe' });

                // Update check run with success
                await github.rest.checks.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  check_run_id: checkRuns[agentName],
                  status: 'completed',
                  conclusion: 'success',
                  output: {
                    title: `Continue Agent: ${agentName} - Success`,
                    summary: `Agent executed successfully.\n\n\`\`\`markdown\n${output}\n\`\`\``
                  }
                });

                // Add to job summary
                summary += `## ✅ ${agentName}\n\`\`\`markdown\n${output}\n\`\`\`\n\n`;

                return { agent: agentName, success: true, output };
              } catch (error) {
                // Update check run with failure
                await github.rest.checks.update({
                  owner: context.repo.owner,
                  repo: context.repo.repo,
                  check_run_id: checkRuns[agentName],
                  status: 'completed',
                  conclusion: 'failure',
                  output: {
                    title: `Continue Agent: ${agentName} - Failed`,
                    summary: `Agent execution failed.\n\n\`\`\`bash\n${error.message}\n\`\`\``
                  }
                });

                // Add to job summary
                summary += `## ❌ ${agentName}\n\`\`\`bash\n${error.message}\n\`\`\`\n\n`;

                throw error;
              }
            });

            // Wait for all agents to complete
            try {
              await Promise.all(promises);
              // Write job summary
              await core.summary.addRaw(summary).write();
            } catch (error) {
              // Fail the job if any agent failed
              core.setFailed(`One or more agents failed: ${error.message}`);
            }

      - name: No agents found
        if: steps.discover.outputs.agents == '[]'
        run: |
          echo "No agent files found in ${{ inputs.agents-path }}"
          echo "# Continue Agents Results" > summary.md
          echo "No agent files found." >> summary.md
          echo "## No agents found" >> summary.md
          echo "No agent files were found in ${{ inputs.agents-path }}" >> summary.md
          cat summary.md >> $GITHUB_STEP_SUMMARY

      - name: Job Summary
        if: always()
        run: |
          if [ -f summary.md ]; then
            cat summary.md >> $GITHUB_STEP_SUMMARY
          fi
